  "communications-and-media-beyond-earth": offworldDailyArticle({
    title:"Communications and Media Beyond Earth",infoboxTitle:"Communications and Media Beyond Earth",eyebrow:"Earth links · local networks · broadcasting · delay · settlement culture",
    lead:"Communications and media beyond Earth include operational radio, traffic and rescue channels, private calls, electronic mail, data networks, recorded entertainment, news, education, worship, local broadcasting, and public ceremonies. Lunar settlements remain near enough for ordinary conversation with a noticeable delay. Mars settlements require asynchronous social habits and more independent local media.",
    canon:"Planetary networks, rescue frequencies, Weltnetz gateways, British communications infrastructure, settlement families, media events, and Mars signal delay are established. Exact bandwidth, frequencies, tariffs, censorship systems, program schedules, and local publications remain open.",
    sections:[
      {id:"operational",title:"Operational communications",html:"<p>Traffic control, docking, surface movement, emergency response, medical consultation, power, maintenance, and weather or radiation warnings receive protected capacity. Personal traffic yields during emergencies.</p>"},
      {id:"earth",title:"Earth links",html:"<p>Lunar voice and video can support conversation with a short round-trip delay. Mars links vary with planetary distance and require messages, recorded calls, and carefully timed exchanges rather than natural interruption and reply.</p>"},
      {id:"networks",title:"Local data networks",html:"<p>Settlement terminals carry work orders, school lessons, medical records, catalogues, messages, reference libraries, software, entertainment, and civic notices. Gateways connect to terrestrial systems without erasing sponsor control.</p>"},
      {id:"news",title:"News and censorship",html:"<p>National broadcasters and corporate services supply most news. Local editors summarize delayed reports, emergency notices, transport schedules, and settlement disputes. Military and commercial secrecy remain substantial.</p>"},
      {id:"family",title:"Family contact",html:"<p>Private calls, recorded messages, photographs, school reports, and shared broadcasts sustain families divided between Earth and settlement. Access time, cost, privacy, and employer monitoring are recurring labor issues.</p>"},
      {id:"local",title:"Local media",html:"<p>Newsletters, audio channels, bulletin systems, amateur video, school productions, sermons, club reports, and settlement histories create a local public sphere. Small populations make anonymity difficult.</p>"},
      {id:"events",title:"Shared broadcasts",html:"<p>Landings, deaths, elections, national days, religious rites, and the Millennium Illumination receive coordinated coverage. Different blocs can share images while narrating their meaning differently.</p>"},
      {id:"delay",title:"A culture of delay",html:"<p>On Mars, residents learn to state complete questions, send supporting records, and act before Earth replies. Political and family relationships become less dependent on immediate approval even while material dependence continues.</p>"}
    ],
    related:[...offworldDailyRelated,{href:"commonwealth-planetary-network.html",kicker:"Major infrastructure",label:"Commonwealth Planetary Network"},{href:"orbital-rescue-service.html",kicker:"Protected emergency traffic",label:"Orbital Rescue Service"},{href:"extraterrestrial-timekeeping.html",kicker:"Schedules and communication windows",label:"Extraterrestrial Timekeeping"}],
    facts:[["Traffic classes","Operational · emergency · public · private"],["Lunar delay","Short but perceptible"],["Mars delay","Variable and conversation-limiting"],["Local network uses","Work · school · medicine · commerce · media"],["Emergency priority","Life and traffic safety"],["Local media","Newsletters · channels · video · bulletins"],["Principal political issue","Control, censorship, privacy, and access"],["Exact technical standards","Open"]],categories:["Space communications","Extraterrestrial media","Planetary networks","Lunar society","Mars settlements"]
  }),

  "extraterrestrial-timekeeping": offworldDailyArticle({
    title:"Extraterrestrial Timekeeping",infoboxTitle:"Extraterrestrial Timekeeping",eyebrow:"Mission clocks · settlement days · lunar phases · Mars local time",
    lead:"Extraterrestrial timekeeping is the use of terrestrial civil time, mission elapsed time, orbital event time, lunar lighting cycles, and Mars local solar time by stations and settlements. No single off-world calendar replaces terrestrial dating by 2010. Operational schedules instead layer local clocks over the legal and commercial time of a sponsoring state.",
    canon:"Twenty-four-hour crew rhythms, international stations, lunar settlements, Mars bases, communication windows, and terrestrial political continuity are established. Exact settlement time zones, abbreviations, calendars, holiday rules, and legal treatment of birth or contract dates remain open.",
    sections:[
      {id:"earth",title:"Terrestrial legal time",html:"<p>Births, marriages, contracts, elections, payroll, insurance, and court records continue to use the calendar and legal time of the responsible terrestrial jurisdiction. Local clocks do not create separate sovereignty.</p>"},
      {id:"mission",title:"Mission and event time",html:"<p>Launch, docking, burns, communications, experiments, maintenance, and emergencies use coordinated event times or elapsed clocks. International operations publish conversions to prevent ambiguity.</p>"},
      {id:"orbit",title:"Orbital stations",html:"<p>Rapid sunrises do not define the workday. Stations preserve a twenty-four-hour circadian schedule tied to their command center, while visiting modules may keep national office hours internally.</p>"},
      {id:"moon",title:"Lunar settlements",html:"<p>The lunar day-night cycle lasts about 29.5 Earth days and cannot organize ordinary waking and sleep. Artificial lighting follows a twenty-four-hour pattern; surface operations also track illumination, Earth visibility, and eclipse.</p>"},
      {id:"mars",title:"Mars local solar time",html:"<p>A Martian solar day is roughly forty minutes longer than an Earth day. Surface teams may schedule field operations by local sols while administration, communications, and family life retain Earth dates.</p>"},
      {id:"several",title:"Several clocks at once",html:"<p>A resident can use local shift time, sponsor-capital time, universal mission time, and the next Earth communication window in one day. Software and wall displays reduce conversion errors.</p>"},
      {id:"holidays",title:"Holidays and anniversaries",html:"<p>Religious and national calendars remain terrestrial. Settlement anniversaries, first landings, arrivals, and local memorials add new observances. A feast may be celebrated at local evening even when its legal date is defined elsewhere.</p>"},
      {id:"disputes",title:"Legal and social disputes",html:"<p>Midnight boundaries affect age, wages, deadlines, elections, and vital records. International or corporate settlements therefore record the governing time standard in advance rather than relying on local custom.</p>"}
    ],
    related:[...offworldDailyRelated,{href:"communications-and-media-beyond-earth.html",kicker:"Communication windows",label:"Communications and Media Beyond Earth"},{href:"government-of-extraterrestrial-settlements.html",kicker:"Legal authority",label:"Government of Extraterrestrial Settlements"},{href:"millennium-dawn.html",kicker:"Global time ceremony",label:"Millennium Dawn"}],
    facts:[["Legal calendar","Terrestrial sponsor calendar"],["Operational standard","Coordinated event or mission time"],["Habitability day","Twenty-four hours"],["Lunar natural cycle","About 29.5 Earth days"],["Martian sol","About 24 h 40 min"],["Common practice","Several simultaneous clocks"],["New observances","Landing and settlement anniversaries"],["Universal civil calendar by 2010","None"]],categories:["Extraterrestrial timekeeping","Space operations","Lunar society","Mars settlements","Calendars"]
  })
